/bin/bash -lc "python3 - <<'PY'
import csv
# read tissue_corr from script output
samples=[]; corr={}
with open('[REDACTED LOCAL PATH]') as f:
 r=csv.DictReader(f,delimiter='\\t')
 for row in r:
  s=row['sample']; t=row['tissue']; v=float(row['pearson_correlation'])
  corr.setdefault(s,{})[t]=v
samples=list(corr)
tissues=list(corr[samples[0]])
# score for assignment dict label->tissue (bijection)
def score(assign):
 return sum(corr[s][assign[s]] for s in samples)
base_assign={s:s for s in samples}
base=score(base_assign)
pairs=[]
for i in range(len(samples)):
 for j in range(i+1,len(samples)):
  a=samples[i]; b=samples[j]; ass=base_assign.copy(); ass[a]=b; ass[b]=a
  pairs.append((score(ass),a,b))
pairs.sort(reverse=True)
print('base',base)
for p in pairs[:20]: print(p)
PY"

